<script lang="ts">
 import {onMount} from "svelte";
 import {planFleetMoves} from "../../miningFleet/fleetMoves.ts";
 import {checkPluginRun,createPilotReach,createPluginRunGrant,pluginGetJson,pluginPostJson,listServerBots,skipWhileBusy,startPluginRun,type GlobalWindowProps,type JsonValue,type PluginRunPolicy,type ServerBot} from "../../../../web/src/plugin-api/index.ts";
 import {createActiveRoster,definiteStartRefusal,safeActiveRosterStorage,type ActivePointer} from "./activeRoster.ts";
 import {createTrainingAccountPass} from "../../training/accountPass.ts";
 import {prepareHeldPilot} from "../../heldPilot.ts";
 let {sessions=[]}:GlobalWindowProps=$props();
 type Pilot={characterID:number;name:string;accountName:string};
 type Site={systemID:number;scannerKey:number;instanceID:number;dungeonID:number;label:string;position:{x:number;y:number;z:number};observedAt:number};
 type Inspection={fleet:{state:"not-in-fleet"}|{state:"ready";fleetID:number;memberIDs:number[]}|null;droneBayError?:string|null;nativeResourcesError?:string|null;siteNames?:Record<string,string>;pilotName?:string|null;shipTypeName?:string|null;stationName?:string|null;systemName?:string|null;droneNames?:Record<string,string>;characterID:number;shipID:number;shipTypeID:number|null;stationID:number;systemID:number;sites:Site[];observedAt:number;droneBay:{itemID:number;typeID:number;quantity:number}[]|null;nativeResources:{cpu:{used:number;total:number};powergrid:{used:number;total:number};fits:boolean}|null};
 type Review={setup:JsonValue;fingerprint:string;pilots:Pilot[];policies:PluginRunPolicy[]};
 let account=$state(""),pilots=$state<Pilot[]>([]),chosen=$state<number[]>([]),leaderID=$state(0),inspected=$state<Inspection[]>([]),siteID=$state(0),busy=$state(false),restoring=$state(true),recoveryUnavailable=$state(false),message=$state(""),bots=$state<readonly ServerBot[]>([]),reviewed=$state<Review|null>(null);
 const selected=$derived(chosen.map(id=>pilots.find(p=>p.characterID===id)).filter((p):p is Pilot=>!!p));
 const sites=$derived(inspected.find(x=>x.characterID===leaderID)?.sites??[]);
 const siteName=(site:Site)=>{const name=inspected.find(x=>x.characterID===leaderID)?.siteNames?.[String(site.instanceID)];return name?`${name} - ${site.label}`:site.label;};
 const fingerprint=$derived(JSON.stringify([chosen,leaderID,siteID,selected.map(p=>[p.characterID,p.accountName]),inspected]));
 const valid=$derived(!!reviewed&&reviewed.fingerprint===fingerprint);
 const fleetBots=$derived(bots.filter(b=>b.kind==="plugin"&&b.plugin?.pluginID==="uoc"&&b.plugin.run==="anomaly-fleet-member"));
 const reach=createPilotReach({pass:createTrainingAccountPass(),held:()=>sessions,known:()=>pilots.map(p=>({characterID:p.characterID,characterName:p.name,accountName:p.accountName})),accounts:()=>[...new Set(pilots.map(p=>p.accountName))]});
 const pointers=createActiveRoster(safeActiveRosterStorage());
 async function restoreActive(){restoring=true;try{const restored=await pointers.restore(async name=>{const options=await reach.accountOptions(name);if(!options.token)throw Error('Account authentication is unavailable.');const response=await(options.fetch??fetch)(`${options.baseUrl??''}/api/pilot-training/characters`,{headers:{authorization:`Bearer ${options.token}`},credentials:'omit'}),body=await response.json();if(!response.ok||body?.ok!==true||typeof body.account!=='string'||body.account.toLowerCase()!==name.toLowerCase()||!Array.isArray(body.characters))throw Error('Account roster is unavailable.');const pilots:Pilot[]=body.characters.map((c:any)=>{if(!Number.isSafeInteger(c?.characterID)||c.characterID<=0||typeof c.name!=='string'||!c.name)throw Error('Account roster is malformed.');return {characterID:c.characterID,name:c.name,accountName:body.account};});const current=await pluginGetJson('uoc','/runs/current',options);if(current.ok!==true||!Array.isArray(current.runs))throw Error('Current run controllers are unavailable.');const registry=current.runs as unknown as {botID:string;characterID:number;operationID:string;operationRunID:string}[],bots=await listServerBots(options);return {account:body.account,pilots,registry,bots};});pilots=[...pilots,...restored.pilots.filter(p=>!pilots.some(x=>x.characterID===p.characterID))];if(restored.unresolved.length)message='A previous fleet start or owner could not be verified; check runs before starting that pilot again.';}catch(e){message=e instanceof Error?e.message:String(e);}finally{recoveryUnavailable=!pointers.persistent();restoring=false;}}
 function reset(){inspected=[];siteID=0;reviewed=null;message="";if(!chosen.includes(leaderID))leaderID=chosen[0]??0;}
 async function refresh(){try{const r=await reach.readServerBots();if(!r.allFailed)bots=r.bots;else message="Could not read anomaly fleet runs.";}catch(e){message=e instanceof Error?e.message:String(e);}}
 async function load(){if(!account.trim()||busy)return;busy=true;reset();try{const name=account.trim(),o=await reach.accountOptions(name);if(!o.token)throw Error("Account authentication is unavailable.");const response=await(o.fetch??fetch)(`${o.baseUrl??""}/api/pilot-training/characters`,{headers:{authorization:`Bearer ${o.token}`},credentials:"omit"}),body=await response.json();if(!response.ok||body?.ok!==true||typeof body.account!=="string"||body.account.toLowerCase()!==name.toLowerCase()||!Array.isArray(body.characters))throw Error("Account roster is unavailable.");const rows:Pilot[]=body.characters.map((c:any)=>{if(!Number.isSafeInteger(c?.characterID)||c.characterID<=0||typeof c.name!=="string"||!c.name)throw Error("Account roster is malformed.");return {characterID:c.characterID,name:c.name,accountName:body.account};});const removed=pilots.filter(p=>p.accountName.toLowerCase()===name.toLowerCase()).map(p=>p.characterID);chosen=chosen.filter(id=>!removed.includes(id));if(!chosen.includes(leaderID))leaderID=chosen[0]??0;pilots=[...pilots.filter(p=>p.accountName.toLowerCase()!==name.toLowerCase()),...rows];}catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function waitInspection(botID:string,p:Pilot):Promise<Inspection>{const until=Date.now()+120000;while(Date.now()<until){const r=await reach.readServerBots();if(r.allFailed||r.missing.length)throw Error("Inspection status is unavailable; check the run before retrying.");bots=r.bots;const bot=r.bots.find(b=>b.botID===botID&&b.characterID===p.characterID);if(bot?.endedAt){if(bot.phase!=="Combat anomaly inspection complete")throw Error(bot.why??"Anomaly inspection failed.");const x=bot.plugin?.readout as unknown as Inspection;if(!x||x.characterID!==p.characterID||![x.shipID,x.stationID,x.systemID].every(n=>Number.isSafeInteger(n)&&n>0)||!Array.isArray(x.sites)||!Number.isFinite(x.observedAt))throw Error("Anomaly inspection is incomplete.");return x;}await new Promise(r=>setTimeout(r,1000));}throw Error("Inspection timed out; check the run before retrying.");}
 async function inspect(){if(busy)return;busy=true;reset();try{const list=[...selected],ids=[...chosen],leader=leaderID;if(list.length<2||list.length>8||list.length!==ids.length||!list.some(p=>p.characterID===leader))throw Error("Choose two to eight pilots and a fleet leader.");const results:Inspection[]=[];for(const p of list){message=`Inspecting ${p.name}...`;const held=sessions.find(s=>s.store.get().station.online?.characterID===p.characterID);if(held)await prepareHeldPilot(held,p.characterID);const options=await reach.accountOptions(p.accountName),check=await checkPluginRun("uoc","anomaly-fleet-inspect",{},options),started=await startPluginRun(p.characterID,"uoc","anomaly-fleet-inspect",check.setup,createPluginRunGrant(check.policy),options);results.push(await waitInspection(started.botID,p));if(JSON.stringify(ids)!==JSON.stringify(chosen)||leaderID!==leader)throw Error("Selection changed during inspection.");}if(new Set(results.map(x=>x.shipID)).size!==results.length||new Set(results.map(x=>x.systemID)).size!==1)throw Error("Pilots need distinct ships in the same system.");inspected=results;message=results.find(x=>x.characterID===leader)?.sites.length?"Choose a discovered combat anomaly.":"No sites were observed from dock. Automatic search will run after Start.";}catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function review(){if(busy)return;busy=true;message="";reviewed=null;try{const site=sites.find(s=>s.instanceID===siteID),list=[...selected],initial=fingerprint;if((siteID!==0&&!site)||inspected.length!==list.length||Date.now()-Math.min(...inspected.map(x=>x.observedAt))>120000)throw Error("Inspect pilots and choose a current site or automatic search.");if(inspected.some(x=>!x.droneBay||!x.droneBay.length))throw Error("Each pilot needs a verified nonempty drone bay.");if(inspected.some(x=>x.nativeResources?.fits!==true))throw Error("Each pilot needs verified sufficient native CPU and powergrid.");if(inspected.some(x=>!x.fleet))throw Error("Native fleet membership is unavailable. Inspect pilots again.");const moves=planFleetMoves(inspected.map(x=>({characterID:x.characterID,shipID:x.shipID,fleet:x.fleet!})),leaderID);if(moves.length){const names=moves.map(m=>list.find(p=>p.characterID===m.characterID)!.name);if(!window.confirm(`${names.join(", ")} will leave their current fleet and join this operation. Continue?`))throw Error("Fleet move was not approved.");if(initial!==fingerprint)throw Error("Selection changed. Inspect again.");}const setup={operationID:`anomaly-${crypto.randomUUID()}`,operationRunID:crypto.randomUUID(),leaderID,...(site?{site}:{systemID:inspected.find(x=>x.characterID===leaderID)!.systemID,siteSearch:{kind:"COMBAT_ANOMALY"}}),...(moves.length?{fleetMoves:moves}:{}),members:inspected.map(x=>({characterID:x.characterID,shipID:x.shipID}))},policies:PluginRunPolicy[]=[];for(const p of list){const r=await checkPluginRun("uoc","anomaly-fleet-member",setup as JsonValue,await reach.accountOptions(p.accountName));if(JSON.stringify(r.setup)!==JSON.stringify(setup))throw Error("Reviewed setup changed.");policies.push(r.policy);}if(initial!==fingerprint)throw Error("Selection changed. Inspect again.");reviewed={setup:setup as JsonValue,fingerprint:initial,pilots:list,policies};}catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function start(){if(!reviewed||!valid||busy||restoring)return;busy=true;const approval=reviewed,started:{botID:string;pilot:Pilot}[]=[];reviewed=null;try{await restoreActive();const setup=approval.setup as {operationID:string;operationRunID:string};for(let i=0;i<approval.pilots.length;i++){const p=approval.pilots[i]!,held=sessions.find(s=>s.store.get().station.online?.characterID===p.characterID);if(held)await prepareHeldPilot(held,p.characterID);if(fingerprint!==approval.fingerprint)throw Error("Selection changed.");const options=await reach.accountOptions(p.accountName),pointer:ActivePointer={accountName:p.accountName,characterID:p.characterID,botID:null,operationID:setup.operationID,operationRunID:setup.operationRunID},grant=createPluginRunGrant(approval.policies[i]!);pointers.begin(pointer);recoveryUnavailable=!pointers.persistent();let b:ServerBot;try{b=await startPluginRun(p.characterID,"uoc","anomaly-fleet-member",approval.setup,grant,options);}catch(error){if(definiteStartRefusal(error))pointers.markRefused(pointer);throw error;}started.push({botID:b.botID,pilot:p});pointers.bind(pointer,b.botID);recoveryUnavailable=!pointers.persistent();}message="Anomaly fleet started.";await refresh();}catch(e){if(started[0])try{await pluginPostJson("uoc",`/runs/${encodeURIComponent(started[0].botID)}/stop`,{},await reach.accountOptions(started[0].pilot.accountName));}catch{}message=`${e instanceof Error?e.message:String(e)} Check runs before retrying.`;await refresh();}finally{busy=false;}}
 async function stop(bot:ServerBot){busy=true;try{await pluginPostJson("uoc",`/runs/${encodeURIComponent(bot.botID)}/stop`,{},await reach.ownerOptions(bot.characterID));message="Fleet stop requested.";await refresh();}catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 onMount(()=>{const tick=skipWhileBusy(async()=>{if(busy)return;await restoreActive();if(!busy)await refresh();});void tick();const timer=setInterval(()=>void tick(),5000);return()=>{clearInterval(timer);void reach.release();};});
</script>
<section aria-label="Combat anomaly fleet">
 <h3>Combat anomalies - drone fleet</h3><p>Two to eight pilots fight one source-qualified anomaly. Completion requires the native site completion event. The fit and encounter difficulty are not guaranteed.</p>
 <label>Account <input bind:value={account} disabled={busy}/></label><button type="button" onclick={load} disabled={busy||!account.trim()}>Load pilots</button>
 <fieldset disabled={busy}><legend>Fleet pilots</legend>{#each pilots as p (p.characterID)}<label><input type="checkbox" value={p.characterID} bind:group={chosen} onchange={reset}/>{p.name} - {p.accountName}</label>{/each}</fieldset>
 <label>Fleet leader <select bind:value={leaderID} onchange={reset} disabled={busy}><option value={0}>Choose leader</option>{#each selected as p (p.characterID)}<option value={p.characterID}>{p.name}</option>{/each}</select></label>
 <button type="button" onclick={inspect} disabled={busy||selected.length<2||!leaderID}>Inspect pilots and sites</button>
 {#if inspected.length}{#each inspected as x (x.characterID)}<p>{x.pilotName??selected.find(p=>p.characterID===x.characterID)?.name??"Pilot"} - {x.shipTypeName??"Ship name unavailable"} - {x.stationName??"Station name unavailable"} - {x.droneBay?`${x.droneBay.reduce((n,d)=>n+d.quantity,0)} drones`:"drone bay unavailable"} - {x.nativeResources?.fits===true?"CPU and powergrid verified":x.nativeResources?.fits===false?"CPU or powergrid insufficient":"CPU and powergrid unavailable"}.</p>{/each}<label>Combat anomaly <select bind:value={siteID} onchange={()=>{reviewed=null}} disabled={busy}><option value={0}>Find automatically after Start</option>{#each sites as site (site.instanceID)}<option value={site.instanceID}>{siteName(site)}</option>{/each}</select></label><details><summary>Advanced details</summary>{#each inspected as x (x.characterID)}<p>{x.pilotName??selected.find(p=>p.characterID===x.characterID)?.name??"Pilot"}: character {x.characterID}; ship {x.shipID}; ship type {x.shipTypeID??"unknown"}; station {x.stationID}; system {x.systemID}; drones {x.droneBay?x.droneBay.map(d=>`${d.quantity} ${x.droneNames?.[String(d.typeID)]??"unknown type"} (type ${d.typeID}, item ${d.itemID})`).join(", ")||"empty":`unavailable${x.droneBayError?`: ${x.droneBayError}`:""}`}; {x.nativeResources?`CPU ${x.nativeResources.cpu.used}/${x.nativeResources.cpu.total}; powergrid ${x.nativeResources.powergrid.used}/${x.nativeResources.powergrid.total}`:`native resources unavailable${x.nativeResourcesError?`: ${x.nativeResourcesError}`:""}`}.</p>{/each}{#each sites as site (site.instanceID)}<p>{site.label}: dungeon {site.dungeonID}; instance {site.instanceID}; scanner key {site.scannerKey}.</p>{/each}</details><button type="button" onclick={review} disabled={busy}>Review fleet</button>{/if}
 {#if reviewed&&valid}<div aria-label="Anomaly fleet review"><p>Pilots: {reviewed.pilots.map(p=>p.name).join(", ")}; site: {sites.find(s=>s.instanceID===siteID)?siteName(sites.find(s=>s.instanceID===siteID)!):"Will undock and search for an eligible combat anomaly in this system"}.</p><details><summary>Advanced review</summary><p>Risks: {reviewed.policies.map(p=>p.riskClasses.join(", ")).join("; ")}.</p><pre>{JSON.stringify(reviewed.setup,null,2)}</pre></details><button type="button" onclick={start} disabled={busy||restoring}>Approve and start fleet</button></div>{/if}
 {#if recoveryUnavailable}<p role="status">Run controls are available in this tab; automatic recovery after reload is unavailable.</p>{/if}{#if message}<p role="status">{message}</p>{/if}<h4>Anomaly fleet runs</h4><button type="button" onclick={refresh} disabled={busy}>Refresh</button>{#each fleetBots as bot (bot.botID)}<div><p>{bot.characterName??"Pilot"} - {bot.phase??bot.status}{bot.endedAt?" - ended":""}</p>{#if bot.why}<p>{bot.why}</p>{/if}{#if !bot.endedAt}<button type="button" onclick={()=>stop(bot)} disabled={busy}>Stop fleet</button>{/if}</div>{/each}
</section>
<style>label{display:grid;gap:.25rem;margin-block:.5rem}fieldset label{display:block}</style>
